const envelope = $json;
if (!envelope || !new Set(['merch_coupon.issued', 'merch.coupon_issued']).has(String(envelope.type)) || envelope.version !== 1) {
  throw new Error('Unsupported CrowdRelay event');
}
const data = envelope.data ?? envelope.payload ?? {};
for (const key of ['email', 'coupon_code', 'discount_percent', 'expires_at']) {
  if (data[key] === undefined || data[key] === null || data[key] === '') {
    throw new Error(`Missing merch coupon field: ${key}`);
  }
}
return [{
  json: {
    event_id: envelope.id,
    fan_id: data.fan_id,
    mail: {
      template: 'crowdrelay-merch-reward',
      to: data.email,
      variables: {
        display_name: data.display_name ?? null,
        coupon_code: data.coupon_code,
        discount_percent: data.discount_percent,
        expires_at: data.expires_at,
        qualified_referral_count: data.qualified_referral_count ?? null
      },
      idempotency_key: envelope.id
    }
  }
}];
